function [s] = ctl_sun_acq(st, cp, hdev)
%CTL_SUN_ACQ  The rotor Sun acquisition: a rate command k (a x s) turning the power face a onto the measured
%   (or propagated) Sun, held to sa_w_max, tracked by a rate loop; no Sun ever seen, rate held at 0.
%   st: CtlState (passed rec)
%   cp: CtlParams (passed rec)
%   hdev: real[1][3] (passed a plain number)
%   returns s: CtlState (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    s = asils.alg.steplaws.CtlState_zero();
    s = st;
    wmax = (cp.sa_w_max_deg_s * (pi / 180));
    wc = zeros(3, 1);
    a = cp.sun_axis;
    if s.s_prop_ok
        sv = asils.pc.unit_(s.s_prop);
        c = [a(2)*sv(3) - a(3)*sv(2); a(3)*sv(1) - a(1)*sv(3); a(1)*sv(2) - a(2)*sv(1)];
        if ((sv(1)*a(1) + sv(2)*a(2) + sv(3)*a(3)) < (-(0.95)))
            c = asils.pc.cross_(a, [1; 0; 0]);
            if (sqrt(c(1)*c(1) + c(2)*c(2) + c(3)*c(3)) < 0.1)
                c = asils.pc.cross_(a, [0; 1; 0]);
            end
            c = asils.pc.unit_(c);
        end
        wc = (c * (wmax / 0.5));
        n = sqrt(wc(1)*wc(1) + wc(2)*wc(2) + wc(3)*wc(3));
        if (n > wmax)
            wc = (wc * (wmax / n));
        end
    end
    gy = asils.pc.cross_(s.w_est, ([cp.j(1, 1)*s.w_est(1) + cp.j(1, 2)*s.w_est(2) + cp.j(1, 3)*s.w_est(3); cp.j(2, 1)*s.w_est(1) + cp.j(2, 2)*s.w_est(2) + cp.j(2, 3)*s.w_est(3); cp.j(3, 1)*s.w_est(1) + cp.j(3, 2)*s.w_est(2) + cp.j(3, 3)*s.w_est(3)] + hdev));
    x = zeros(3, 1);
    for i = (0):((3) - 1)
        x((i) + 1) = (cp.sa_kd * (wc((i) + 1) - s.w_est((i) + 1)));
    end
    s.tau_req = ([cp.j(1, 1)*x(1) + cp.j(1, 2)*x(2) + cp.j(1, 3)*x(3); cp.j(2, 1)*x(1) + cp.j(2, 2)*x(2) + cp.j(2, 3)*x(3); cp.j(3, 1)*x(1) + cp.j(3, 2)*x(2) + cp.j(3, 3)*x(3)] + gy);
end
